import React from 'react'
import { useTranslation } from 'react-i18next'
import { useForm } from '@tanstack/react-form'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { z } from 'zod/v4'
import {
	useUpdateFees,
	getTaxFeeConfigQueryKey,
	ShippingCostModeEnum,
	shippingCostModeSchema,
	updateFeesMutationRequestSchema,
	CurrencyCodeEnum,
	currencyCodeSchema,
} from '@bk-dash/client-typescript/typescript'
import type { GetTaxFeeConfig200 } from '@bk-dash/client-typescript/typescript'

import { cn } from '@/lib/utils'
import { DeepPartial } from '@/lib'
import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { Select } from '@/components/ui/select'
import { CurrencyInput } from '@/components/ui/currency-input'

// Flat UI schema for form field validation only — NOT the API body shape.
// The discriminated-union API shape is validated via updateFeesMutationRequestSchema at submit.
const uiSchema = z.object({
	mode: shippingCostModeSchema.optional(),
	averageShippingFee: z
		.object({
			amountCents: z.number().int().min(0),
			currency: currencyCodeSchema,
		})
		.optional(),
})

const MODES_WITH_AMOUNT = [ShippingCostModeEnum.AVERAGE_PER_SALE, ShippingCostModeEnum.BY_PRODUCT_QUANTITY] as string[]

// A15: compose ComponentProps so parents can place/style this form
type ShippingFeeFormProps = React.ComponentProps<'form'> & {
	defaultValues: GetTaxFeeConfig200['shipping']
}

export function ShippingFeeForm({ defaultValues, className, ...props }: ShippingFeeFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()

	// H1: declare onSuccess on the hook, not on each mutateAsync call site
	const updateFees = useUpdateFees({
		mutation: {
			onSuccess: () => {
				toast.success(t('taxesAndFees.shipping.saveSuccess'))
				queryClient.invalidateQueries({ queryKey: getTaxFeeConfigQueryKey() })
			},
		},
	})

	// A5/A6: typed DeepPartial const — no inline cast, no useForm<T> type arg
	const formDefaults: DeepPartial<z.infer<typeof uiSchema>> = {
		mode: defaultValues.mode,
		averageShippingFee: {
			amountCents: defaultValues.averageShippingFee.amountCents,
			currency: defaultValues.averageShippingFee.currency,
		},
	}

	const form = useForm({
		defaultValues: formDefaults,
		validators: { onChange: uiSchema },
		onSubmit: async ({ value }) => {
			const { mode, averageShippingFee } = value

			const shippingFee =
				(mode === ShippingCostModeEnum.AVERAGE_PER_SALE || mode === ShippingCostModeEnum.BY_PRODUCT_QUANTITY) &&
				averageShippingFee?.amountCents !== undefined &&
				averageShippingFee?.currency !== undefined
					? { mode, value: { amountCents: averageShippingFee.amountCents, currency: averageShippingFee.currency } }
					: { mode: mode ?? 'NONE' }

			const body = {
				shippingFee,
				effectiveFrom: new Date().toISOString(),
			}

			const parsed = updateFeesMutationRequestSchema.safeParse(body)
			if (!parsed.success) return

			await updateFees.mutateAsync({ data: parsed.data })
		},
	})

	return (
		// A15: forward className + native form attrs; keep form's own onSubmit last
		<form
			noValidate
			className={cn(className)}
			{...props}
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
		>
			<FieldGroup>
				{/* A13: enum-driven Select — no Object.values().map() + no 'as' cast */}
				<form.Field name="mode">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('taxesAndFees.shipping.mode')}</FieldLabel>
								<Select
									enum={ShippingCostModeEnum}
									i18nPrefix="enums.ShippingCostMode"
									value={field.state.value}
									onValueChange={field.handleChange}
									placeholder="taxesAndFees.shipping.modePlaceholder"
									id={field.name}
									aria-invalid={isInvalid}
								/>
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>

				{/* A12: CurrencyInput for the money field — shown only for modes that require it */}
				<form.Subscribe selector={s => s.values.mode}>
					{mode =>
						MODES_WITH_AMOUNT.includes(mode ?? '') ? (
							<form.Field name="averageShippingFee">
								{field => {
									const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
									return (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('taxesAndFees.shipping.averageShippingFee')}</FieldLabel>
											<CurrencyInput
												id={field.name}
												amountCents={field.state.value?.amountCents ?? 0}
												currency={field.state.value?.currency ?? CurrencyCodeEnum.BRL}
												onAmountChange={cents => field.handleChange({ ...field.state.value, amountCents: cents })}
												onCurrencyChange={c => field.handleChange({ ...field.state.value, currency: c })}
											/>
											{isInvalid && <FieldError errors={field.state.meta.errors} />}
										</Field>
									)
								}}
							</form.Field>
						) : null
					}
				</form.Subscribe>

				<form.Subscribe
					selector={state => ({
						canSubmit: state.canSubmit,
						isSubmitting: state.isSubmitting,
						values: state.values,
					})}
				>
					{({ canSubmit, isSubmitting, values }) => {
						const isPending = isSubmitting || updateFees.isPending
						const isDisabled = !canSubmit || isPending || !uiSchema.safeParse(values).success
						return (
							<Button type="submit" disabled={isDisabled} className="w-fit">
								{isPending && <Spinner className="mr-2" />}
								{t('taxesAndFees.save')}
							</Button>
						)
					}}
				</form.Subscribe>
			</FieldGroup>
		</form>
	)
}

