import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { z } from 'zod'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'

import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter } from '@/components/ui/sheet'
import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { useConnectIntegrationSheetStore } from '../../-stores/useConnectIntegrationSheetStore'

function getDefaultCredentials(platform: string, connectionMode: string): Record<string, string> {
	if (platform === 'SHOPIFY' && connectionMode === 'CREDENTIALS') {
		return { shopDomain: '', clientId: '', clientSecret: '' }
	}
	if (platform === 'SHOPIFY_PAYMENTS' && connectionMode === 'CREDENTIALS') {
		return { storeDomain: '', accessToken: '' }
	}
	if (platform === 'YAMPI' && connectionMode === 'CREDENTIALS') {
		return { alias: '', userToken: '', userSecretKey: '' }
	}
	return {}
}

// Form values shape — credentials is the dynamic sub-object.
// z.record keeps all credential field paths typed as string (not never) inside
// TanStack Form. Per-variant validation is deferred to the SDK union schema at
// submit time via connectIntegrationMutationRequestSchema.safeParse().
const formSchema = z.object({
	credentials: z.record(z.string(), z.string()),
})

/**
 * ConnectIntegrationSheet — global sheet (opened via Zustand store) that renders
 * a TanStack Form for CREDENTIALS-mode integrations.
 * Mounted once in IntegrationsListSection; no props needed.
 */
export function ConnectIntegrationSheet() {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const isOpen = useConnectIntegrationSheetStore(s => s.isOpen)
	const selectedItem = useConnectIntegrationSheetStore(s => s.selectedItem)
	const close = useConnectIntegrationSheetStore(s => s.close)

	// H1: onSuccess declared on the hook — fires for every call, keeps mutateAsync clean
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				close()
			},
		},
	})

	const defaultCredentials = selectedItem ? getDefaultCredentials(selectedItem.platform, selectedItem.connectionMode) : {}

	const form = useForm({
		defaultValues: { credentials: defaultCredentials },
		validators: { onChange: formSchema },
		onSubmit: async ({ value }) => {
			if (!selectedItem) return

			// Assemble the platform-specific payload and let the SDK union schema
			// act as the final validator. safeParse narrows the type to the correct
			// discriminated variant before calling mutateAsync.
			const payload = {
				connectionMode: selectedItem.connectionMode,
				type: selectedItem.type,
				platform: selectedItem.platform,
				credentials: value.credentials,
			}

			const sdkParsed = connectIntegrationMutationRequestSchema.safeParse(payload)
			if (!sdkParsed.success) return

			await connect.mutateAsync({ data: sdkParsed.data })
			form.reset()
		},
	})

	const handleOpenChange = (open: boolean) => {
		if (!open) {
			close()
			form.reset()
		}
	}

	const isShopify = selectedItem?.platform === 'SHOPIFY' && selectedItem.connectionMode === 'CREDENTIALS'
	const isShopifyPayments = selectedItem?.platform === 'SHOPIFY_PAYMENTS' && selectedItem.connectionMode === 'CREDENTIALS'
	const isYampi = selectedItem?.platform === 'YAMPI' && selectedItem.connectionMode === 'CREDENTIALS'

	return (
		<Sheet open={isOpen} onOpenChange={handleOpenChange}>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>
						{selectedItem ? t('integrations.sheet.titleWith', { name: selectedItem.name }) : t('integrations.sheet.title')}
					</SheetTitle>
					<SheetDescription>{t('integrations.sheet.description')}</SheetDescription>
				</SheetHeader>

				<form
					className="flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2"
					noValidate
					onSubmit={e => {
						e.preventDefault()
						e.stopPropagation()
						form.handleSubmit()
					}}
				>
					<FieldGroup>
						{isShopify && (
							<>
								<form.Field name="credentials.shopDomain">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.shopDomain')}</FieldLabel>
											<Input
												id={field.name}
												type="text"
												autoComplete="off"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>

								<form.Field name="credentials.clientId">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientId')}</FieldLabel>
											<Input
												id={field.name}
												type="text"
												autoComplete="off"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>

								<form.Field name="credentials.clientSecret">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientSecret')}</FieldLabel>
											<Input
												id={field.name}
												type="password"
												autoComplete="new-password"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>
							</>
						)}

						{isShopifyPayments && (
							<>
								<form.Field name="credentials.storeDomain">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.storeDomain')}</FieldLabel>
											<Input
												id={field.name}
												type="text"
												autoComplete="off"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>

								<form.Field name="credentials.accessToken">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.accessToken')}</FieldLabel>
											<Input
												id={field.name}
												type="password"
												autoComplete="new-password"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>
							</>
						)}

						{isYampi && (
							<>
								<form.Field name="credentials.alias">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.alias')}</FieldLabel>
											<Input
												id={field.name}
												type="text"
												autoComplete="off"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>

								<form.Field name="credentials.userToken">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.userToken')}</FieldLabel>
											<Input
												id={field.name}
												type="text"
												autoComplete="off"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>

								<form.Field name="credentials.userSecretKey">
									{field => (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('integrations.sheet.userSecretKey')}</FieldLabel>
											<Input
												id={field.name}
												type="password"
												autoComplete="new-password"
												value={field.state.value ?? ''}
												onBlur={field.handleBlur}
												onChange={e => field.handleChange(e.target.value)}
											/>
											{field.state.meta.errors[0] && <FieldError>{String(field.state.meta.errors[0]?.message ?? '')}</FieldError>}
										</Field>
									)}
								</form.Field>
							</>
						)}
					</FieldGroup>

					<SheetFooter>
						<form.Subscribe selector={s => ({ canSubmit: s.canSubmit, isSubmitting: s.isSubmitting, values: s.values })}>
							{({ canSubmit, isSubmitting, values }) => {
								const isPending = isSubmitting || connect.isPending
								const isDisabled = !canSubmit || isPending || !formSchema.safeParse(values).success
								return (
									<Button type="submit" disabled={isDisabled} className="w-full">
										{isPending && <Spinner className="mr-2" />}
										{t('integrations.sheet.submit')}
									</Button>
								)
							}}
						</form.Subscribe>
					</SheetFooter>
				</form>
			</SheetContent>
		</Sheet>
	)
}

