/**
 * Per-variant credential forms for the Connect-Integration sheet.
 *
 * The connect body is a discriminated union (`connectIntegrationMutationRequestSchema`) — one member
 * per (platform, connectionMode). Rather than flatten it into a `z.record` catch-all + dynamic field
 * dispatch, each variant gets its OWN small form: explicit typed fields, type narrowed from the SDK
 * union via `Extract`, validated against the SDK union directly. Adding a platform = add a form +
 * one map entry; nothing here second-guesses the contract.
 */
import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

import type { DeepPartial } from '@/lib'
import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'

export interface CredentialFormProps {
	/** Called after a successful connect (the sheet closes on this). */
	onConnected: () => void
}

// Variant types narrowed straight from the SDK union — no hand-rolled credential shapes.
type ShopifyVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY'; connectionMode: 'CREDENTIALS' }>
type ShopifyPaymentsVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY_PAYMENTS'; connectionMode: 'CREDENTIALS' }>
type YampiVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'YAMPI'; connectionMode: 'CREDENTIALS' }>

// Shared mutation wiring (H1: hook-level onSuccess). The forms stay per-variant; only the infra is shared.
function useConnectMutation(onConnected: () => void) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	return useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
}

// ─────────────────────────────────────────────────────────────────────────────

function ShopifyCredentialsForm({ onConnected }: CredentialFormProps) {
	const { t } = useTranslation()
	const connect = useConnectMutation(onConnected)

	const defaultValues: DeepPartial<ShopifyVariant> = {
		connectionMode: 'CREDENTIALS',
		platform: 'SHOPIFY',
		credentials: { shopDomain: '', clientId: '', clientSecret: '' },
	}

	const form = useForm({
		defaultValues,
		validators: { onChange: connectIntegrationMutationRequestSchema },
		onSubmit: async ({ value }) => {
			const result = connectIntegrationMutationRequestSchema.safeParse(value)
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})

	return (
		<ConnectForm form={form} pending={connect.isPending}>
			<form.Field name="credentials.shopDomain">
				{field => <CredentialField field={field} label={t('integrations.sheet.shopDomain')} />}
			</form.Field>
			<form.Field name="credentials.clientId">
				{field => <CredentialField field={field} label={t('integrations.sheet.clientId')} />}
			</form.Field>
			<form.Field name="credentials.clientSecret">
				{field => <CredentialField field={field} label={t('integrations.sheet.clientSecret')} secret />}
			</form.Field>
		</ConnectForm>
	)
}

function ShopifyPaymentsCredentialsForm({ onConnected }: CredentialFormProps) {
	const { t } = useTranslation()
	const connect = useConnectMutation(onConnected)

	const defaultValues: DeepPartial<ShopifyPaymentsVariant> = {
		connectionMode: 'CREDENTIALS',
		platform: 'SHOPIFY_PAYMENTS',
		credentials: { storeDomain: '', accessToken: '' },
	}

	const form = useForm({
		defaultValues,
		validators: { onChange: connectIntegrationMutationRequestSchema },
		onSubmit: async ({ value }) => {
			const result = connectIntegrationMutationRequestSchema.safeParse(value)
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})

	return (
		<ConnectForm form={form} pending={connect.isPending}>
			<form.Field name="credentials.storeDomain">
				{field => <CredentialField field={field} label={t('integrations.sheet.storeDomain')} />}
			</form.Field>
			<form.Field name="credentials.accessToken">
				{field => <CredentialField field={field} label={t('integrations.sheet.accessToken')} secret />}
			</form.Field>
		</ConnectForm>
