}

function YampiCredentialsForm({ onConnected }: CredentialFormProps) {
	const { t } = useTranslation()
	const connect = useConnectMutation(onConnected)

	const defaultValues: DeepPartial<YampiVariant> = {
		connectionMode: 'CREDENTIALS',
		platform: 'YAMPI',
		credentials: { alias: '', userToken: '', userSecretKey: '' },
	}

	const form = useForm({
		defaultValues,
		validators: { onChange: connectIntegrationMutationRequestSchema },
		onSubmit: async ({ value }) => {
