			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})

	return (
		<ConnectForm form={form} pending={connect.isPending}>
			<form.Field name="credentials.alias">
				{field => <CredentialField field={field} label={t('integrations.sheet.alias')} />}
			</form.Field>
			<form.Field name="credentials.userToken">
				{field => <CredentialField field={field} label={t('integrations.sheet.userToken')} />}
			</form.Field>
			<form.Field name="credentials.userSecretKey">
				{field => <CredentialField field={field} label={t('integrations.sheet.userSecretKey')} secret />}
			</form.Field>
		</ConnectForm>
	)
}

// ─────────────────────────────────────────────────────────────────────────────
// Small shared presentational pieces (input row + form shell). These don't touch the
// schema — each variant above owns its fields + SDK-union validation.

// biome-ignore lint/suspicious/noExplicitAny: TanStack field type differs per form; the row is purely presentational.
function CredentialField({ field, label, secret = false }: { field: any; label: string; secret?: boolean }) {
	const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
	return (
		<Field>
			<FieldLabel htmlFor={field.name}>{label}</FieldLabel>
			<Input
				id={field.name}
				type={secret ? 'password' : 'text'}
				autoComplete={secret ? 'new-password' : 'off'}
				value={field.state.value ?? ''}
				onBlur={field.handleBlur}
				onChange={(e: React.ChangeEvent<HTMLInputElement>) => field.handleChange(e.target.value)}
				aria-invalid={isInvalid}
			/>
			{isInvalid && <FieldError errors={field.state.meta.errors} />}
		</Field>
	)
}

function ConnectForm({
	form,
	pending,
	children,
}: {
	// biome-ignore lint/suspicious/noExplicitAny: variant forms have distinct TFormData; the shell only drives submit.
	form: any
	pending: boolean
	children: React.ReactNode
}) {
	const { t } = useTranslation()
	return (
		<form
			className="flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2"
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
		>
			<FieldGroup>{children}</FieldGroup>
			<SheetFooter>
				<form.Subscribe selector={(s: { canSubmit: boolean; isSubmitting: boolean }) => ({ canSubmit: s.canSubmit, isSubmitting: s.isSubmitting })}>
					{({ canSubmit, isSubmitting }: { canSubmit: boolean; isSubmitting: boolean }) => {
						const isPending = isSubmitting || pending
						return (
							<Button type="submit" disabled={!canSubmit || isPending} className="w-full">
								{isPending && <Spinner className="mr-2" />}
								{t('integrations.sheet.submit')}
							</Button>
						)
					}}
				</form.Subscribe>
			</SheetFooter>
		</form>
	)
}

// Registry: (platform:connectionMode) → its form. The sheet looks the variant up here.
export const CREDENTIAL_FORMS: Record<string, (props: CredentialFormProps) => React.ReactElement> = {
	'SHOPIFY:CREDENTIALS': ShopifyCredentialsForm,
	'SHOPIFY_PAYMENTS:CREDENTIALS': ShopifyPaymentsCredentialsForm,
	'YAMPI:CREDENTIALS': YampiCredentialsForm,
}

