						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientId')}</FieldLabel>
								<Input id={field.name} type="text" autoComplete="off" value={field.state.value ?? ''} onBlur={field.handleBlur} onChange={e => field.handleChange(e.target.value)} aria-invalid={isInvalid} />
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>
				<form.Field name="credentials.clientSecret">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientSecret')}</FieldLabel>
								<Input id={field.name} type="password" autoComplete="new-password" value={field.state.value ?? ''} onBlur={field.handleBlur} onChange={e => field.handleChange(e.target.value)} aria-invalid={isInvalid} />
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>
			</FieldGroup>
			<SubmitFooter form={form} pending={connect.isPending} />
		</form>
	)
}

