// Submit footer — generic over the variant form via TanStack's own ReactFormExtendedApi inference.
function SubmitFooter<TForm extends { Subscribe: React.ComponentType<{ selector: (s: { canSubmit: boolean; isSubmitting: boolean }) => { canSubmit: boolean; isSubmitting: boolean }; children: (s: { canSubmit: boolean; isSubmitting: boolean }) => React.ReactNode }> }>({
	form,
	pending,
}: {
	form: TForm
	pending: boolean
}) {
	const { t } = useTranslation()
	return (
		<SheetFooter>
			<form.Subscribe selector={s => ({ canSubmit: s.canSubmit, isSubmitting: s.isSubmitting })}>
				{({ canSubmit, isSubmitting }) => (
					<Button type="submit" disabled={!canSubmit || isSubmitting || pending} className="w-full">
