/**
 * Per-variant credential forms for the Connect-Integration sheet.
 *
 * The connect body is a discriminated union (`connectIntegrationMutationRequestSchema`) — one member
 * per (platform, connectionMode). Rather than flatten it into a `z.record` catch-all + dynamic field
 * dispatch, each variant gets its OWN small form: explicit, concretely-typed fields, the shape narrowed
 * from the SDK union via `Extract`, validated against the SDK union directly. Adding a platform = add a
 * form + one map entry. Fields are deliberately duplicated across forms so each stays fully typed (no
 * `any`, no cross-variant abstraction).
 */
import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

import type { DeepPartial } from '@/lib'
import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'

export interface CredentialFormProps {
	/** Called after a successful connect (the sheet closes on this). */
	onConnected: () => void
}

// TFormData is the SDK union itself, so `validators.onChange` = the SDK schema lines up exactly (a
// narrowed Extract<> rejects the union validator). Each form still sets its own platform literal +
// renders only its variant's fields, and `connectIntegrationMutationRequestSchema.safeParse` at submit
// narrows to the right member. No hand-rolled credential shapes.
type ConnectForm = DeepPartial<ConnectIntegrationMutationRequest>

// Shared mutation wiring (H1: hook-level onSuccess). The forms stay per-variant; only the infra is shared.
function useConnectMutation(onConnected: () => void) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	return useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
}

const formShell = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

