function SubmitFooter<TForm extends { Subscribe: React.ComponentType<{ selector: (s: { canSubmit: boolean; isSubmitting: boolean }) => { canSubmit: boolean; isSubmitting: boolean }; children: (s: { canSubmit: boolean; isSubmitting: boolean }) => React.ReactNode }> }>({
