	/** Called after a successful connect (the sheet closes on this). */
	onConnected: () => void
}

// Variant types narrowed straight from the SDK union — no hand-rolled credential shapes.
type ShopifyVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY'; connectionMode: 'CREDENTIALS' }>
type ShopifyPaymentsVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY_PAYMENTS'; connectionMode: 'CREDENTIALS' }>
type YampiVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'YAMPI'; connectionMode: 'CREDENTIALS' }>

// Shared mutation wiring (H1: hook-level onSuccess). The forms stay per-variant; only the infra is shared.
function useConnectMutation(onConnected: () => void) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	return useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
}

const FORM_SHELL = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

// ── Shopify (CREDENTIALS) ────────────────────────────────────────────────────
function ShopifyCredentialsForm({ onConnected }: CredentialFormProps) {
	const { t } = useTranslation()
	const connect = useConnectMutation(onConnected)
	const defaultValues: DeepPartial<ShopifyVariant> = {
		connectionMode: 'CREDENTIALS',
		platform: 'SHOPIFY',
		credentials: { shopDomain: '', clientId: '', clientSecret: '' },
	}
	const form = useForm({
		defaultValues,
		onSubmit: async ({ value }) => {
			const result = connectIntegrationMutationRequestSchema.safeParse(value)
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})
	return (
		<form
			className={FORM_SHELL}
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
		>
			<FieldGroup>
				<form.Field name="credentials.shopDomain">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.shopDomain')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="credentials.clientId">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientId')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="credentials.clientSecret">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientSecret')}</FieldLabel>
							<Input
								id={field.name}
								type="password"
								autoComplete="new-password"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
			</FieldGroup>
			<form.Subscribe selector={s => ({ values: s.values, isSubmitting: s.isSubmitting })}>
				{({ values, isSubmitting }) => <ConnectSubmit values={values} pending={isSubmitting || connect.isPending} />}
			</form.Subscribe>
		</form>
	)
}

