// Submit button gated by the SDK union (the discriminated body's real validator). `values` is a
// partial connect body; safeParse succeeds only once the active member is complete.
function ConnectSubmit({
	values,
	pending,
}: {
	values: ConnectIntegrationMutationRequest | DeepPartial<ConnectIntegrationMutationRequest>
	pending: boolean
}) {
	const { t } = useTranslation()
	const isValid = connectIntegrationMutationRequestSchema.safeParse(values).success
	return (
		<SheetFooter>
			<Button type="submit" disabled={!isValid || pending} className="w-full">
				{pending && <Spinner className="mr-2" />}
				{t('integrations.sheet.submit')}
			</Button>
		</SheetFooter>
	)
}

// Registry: (platform:connectionMode) → its form. The sheet looks the variant up here.
export const CREDENTIAL_FORMS: Record<string, (props: CredentialFormProps) => React.ReactElement> = {
	'SHOPIFY:CREDENTIALS': ShopifyCredentialsForm,
	'SHOPIFY_PAYMENTS:CREDENTIALS': ShopifyPaymentsCredentialsForm,
	'YAMPI:CREDENTIALS': YampiCredentialsForm,
}

