/**
 * ConnectIntegrationSheet — global sheet (opened via Zustand store) for CREDENTIALS-mode integrations.
 * Mounted once in IntegrationsListSection; no props needed. The actual form is chosen per
 * (platform, connectionMode) from CREDENTIAL_FORMS — each variant is its own typed form.
 */
export function ConnectIntegrationSheet() {
	const { t } = useTranslation()
	const isOpen = useConnectIntegrationSheetStore(s => s.isOpen)
	const selectedItem = useConnectIntegrationSheetStore(s => s.selectedItem)
	const close = useConnectIntegrationSheetStore(s => s.close)

	const VariantForm = selectedItem ? CREDENTIAL_FORMS[`${selectedItem.platform}:${selectedItem.connectionMode}`] : undefined

	return (
		<Sheet
			open={isOpen}
			onOpenChange={open => {
				if (!open) close()
			}}
		>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>
						{selectedItem ? t('integrations.sheet.titleWith', { name: selectedItem.name }) : t('integrations.sheet.title')}
					</SheetTitle>
					<SheetDescription>{t('integrations.sheet.description')}</SheetDescription>
				</SheetHeader>

				{VariantForm ? <VariantForm onConnected={close} /> : null}
			</SheetContent>
		</Sheet>
	)
}

