import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'

import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'

export interface AppmaxManualFormProps {
	onConnected: () => void
}

export function AppmaxManualForm({ onConnected }: AppmaxManualFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})

	const handleConnect = async () => {
		const r = connectIntegrationMutationRequestSchema.safeParse({
			connectionMode: 'MANUAL',
			platform: 'APPMAX',
			credentials: {},
		})
		if (!r.success) return
		await connect.mutateAsync({ data: r.data })
	}

	return (
		<div className="flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2">
			<p className="text-muted-foreground text-sm">{t('integrations.sheet.manualDescription')}</p>
			<SheetFooter>
				<Button
					type="button"
					disabled={connect.isPending}
					className="w-full"
					onClick={handleConnect}
				>
					{connect.isPending && <Spinner className="mr-2" />}
					{t('integrations.sheet.connectManual')}
				</Button>
			</SheetFooter>
		</div>
	)
}

import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'

export interface HotmartCredentialsFormProps {
	onConnected: () => void
}

type HotmartVariant = Extract<
	ConnectIntegrationMutationRequest,
	{ platform: 'HOTMART'; connectionMode: 'CREDENTIALS' }
>

const FORM_SHELL = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

export function HotmartCredentialsForm({ onConnected }: HotmartCredentialsFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})

	const handleConfirm = async () => {
		const payload: HotmartVariant = {
			connectionMode: 'CREDENTIALS',
			platform: 'HOTMART',
			credentials: {},
		}
		const result = connectIntegrationMutationRequestSchema.safeParse(payload)
		if (!result.success) return
		await connect.mutateAsync({ data: result.data })
	}

	return (
		<div className={FORM_SHELL}>
			<p className="text-muted-foreground text-sm">{t('integrations.sheet.manualDescription')}</p>
			<SheetFooter>
				<Button
					type="button"
					className="w-full"
					disabled={connect.isPending}
					onClick={handleConfirm}
				>
					{connect.isPending && <Spinner className="mr-2" />}
					{t('integrations.sheet.connectManual')}
				</Button>
			</SheetFooter>
		</div>
	)
}

