import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

import type { DeepPartial } from '@/lib'
import { Field, FieldLabel, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'

export interface ShopifyCredentialsFormProps {
	onConnected: () => void
}

type ShopifyVariant = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY'; connectionMode: 'CREDENTIALS' }>

const FORM_SHELL = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

function ConnectSubmit({
	values,
	pending,
}: {
	values: ConnectIntegrationMutationRequest | DeepPartial<ConnectIntegrationMutationRequest>
	pending: boolean
}) {
	const { t } = useTranslation()
	const isValid = connectIntegrationMutationRequestSchema.safeParse(values).success
	return (
		<SheetFooter>
			<Button type="submit" disabled={!isValid || pending} className="w-full">
				{pending && <Spinner className="mr-2" />}
				{t('integrations.sheet.submit')}
			</Button>
		</SheetFooter>
	)
}

export function ShopifyCredentialsForm({ onConnected }: ShopifyCredentialsFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
	const defaultValues: DeepPartial<ShopifyVariant> = {
		connectionMode: 'CREDENTIALS',
		platform: 'SHOPIFY',
		credentials: { shopDomain: '', clientId: '', clientSecret: '' },
	}
	const form = useForm({
		defaultValues,
		onSubmit: async ({ value }) => {
			const result = connectIntegrationMutationRequestSchema.safeParse(value)
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})
	return (
		<form
			className={FORM_SHELL}
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
		>
			<FieldGroup>
				<form.Field name="credentials.shopDomain">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.shopDomain')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="credentials.clientId">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientId')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="credentials.clientSecret">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientSecret')}</FieldLabel>
							<Input
								id={field.name}
								type="password"
								autoComplete="new-password"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
			</FieldGroup>
			<form.Subscribe selector={s => ({ values: s.values, isSubmitting: s.isSubmitting })}>
				{({ values, isSubmitting }) => <ConnectSubmit values={values} pending={isSubmitting || connect.isPending} />}
			</form.Subscribe>
		</form>
	)
}

