import { useAuthorizeIntegration } from '@bk-dash/client-typescript/typescript'
import type { AuthorizeIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

/**
 * OAuth connect, mirroring bk-dash-frontend's flow: mint an authorize URL for the
 * (type, platform) coordinate via `authorizeIntegration`, then redirect the window to it.
 * OAuth is NOT part of the connect HTTP body (PlatformConnectNonOAuthBodySchema) — it always
 * goes through this authorize → redirect → callback (`useIntegrationOAuthCallback`) round-trip.
 *
 * Per-platform OAuth forms call `start({ type, platform })` with their own literal coordinate.
 */
export function useOauth() {
	const authorize = useAuthorizeIntegration()

	const start = async (coordinate: AuthorizeIntegrationMutationRequest) => {
		const { authorizeUrl } = await authorize.mutateAsync({ data: coordinate })
		window.location.href = authorizeUrl
	}

	return { start, isPending: authorize.isPending }
}

