// Register shared value-object schemas so any controller body/response that embeds
// MoneySchema or SignedMoneySchema emits a `$ref: '#/components/schemas/Money'`
// instead of inlining the full object definition.
openapi.registerSchemas({ MoneySchema, SignedMoneySchema })

export default ctx.router

