import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { UpdateFees, UpdateFeesInputSchema, UpdateFeesOutputSchema } from '../usecases/UpdateFees'

export const UpdateFeesControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), session: z.object({ storeId: z.uuid() }) }),
	body: UpdateFeesInputSchema.omit({ userId: true, storeId: true }).extend({
		effectiveFrom: z.stringToDate(),
	}),
})

export const UpdateFeesControllerOutputSchema = UpdateFeesOutputSchema

@injectable()
export class UpdateFeesController extends Controller<typeof UpdateFeesControllerInputSchema, typeof UpdateFeesControllerOutputSchema> {
	readonly path = '/fees-configuration'
	readonly method = 'put' as const
	readonly description = 'Update Fees; places typed fee entries onto per-key timelines'
	readonly inputSchema = UpdateFeesControllerInputSchema
	readonly outputSchema = UpdateFeesControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateFees) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.session.storeId,
			gatewayFees: request.body.gatewayFees,
			checkoutFee: request.body.checkoutFee,
			shippingFee: request.body.shippingFee,
			effectiveFrom: request.body.effectiveFrom,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { PaymentGateway, PaymentMethod, CheckoutPlatform, ShippingCostMode } from '@bk-dash/contracts-typescript/wire/enums'
import { MoneySchema } from '../../shared/objects'
import { Fees } from '../entities/Fees'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

export const GatewayFeeBodySchema = z.object({
	platform: z.enum(PaymentGateway),
	paymentMethod: z.enum(PaymentMethod),
	variable: z.number().min(0).max(1),
	fixed: MoneySchema,
})
export const CheckoutFeeBodySchema = z.object({ platform: z.enum(CheckoutPlatform), rate: z.number().min(0).max(1) })
export const ShippingFeeBodySchema = z.discriminatedUnion('mode', [
	z.object({ mode: z.literal(ShippingCostMode.NONE) }),
	z.object({ mode: z.literal(ShippingCostMode.PAID_BY_CUSTOMER_AT_CHECKOUT) }),
	z.object({ mode: z.literal(ShippingCostMode.AVERAGE_PER_SALE), value: MoneySchema }),
	z.object({ mode: z.literal(ShippingCostMode.BY_PRODUCT_QUANTITY), value: MoneySchema }),
])

export const UpdateFeesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	gatewayFees: z.array(GatewayFeeBodySchema).optional(),
	checkoutFee: CheckoutFeeBodySchema.optional(),
	shippingFee: ShippingFeeBodySchema.optional(),
	effectiveFrom: z.date(),
})

export const UpdateFeesOutputSchema = z.object({ feesConfigurationId: z.uuid(), effectiveFrom: z.date() })

/**
 * UpdateFees. Find-or-create the store's single
 * FeesConfiguration row, then place each supplied fee block onto its
 * Timeline. Emits FeesConfigurationUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateFees extends Handler<typeof UpdateFeesInputSchema, typeof UpdateFeesOutputSchema> {
	readonly name = 'update_fees' as const
	readonly inputSchema = UpdateFeesInputSchema
	readonly outputSchema = UpdateFeesOutputSchema

	constructor(private readonly fees: FeesConfigurationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const fc = (await this.fees.findByStoreId(input.storeId, tx)) ?? Fees.create({ storeId: input.storeId })
			const at = { startDate: input.effectiveFrom, endDate: null as Date | null }
			for (const g of input.gatewayFees ?? []) fc.placeGatewayFee({ ...g, ...at })
			if (input.checkoutFee) fc.placeCheckoutFee({ ...input.checkoutFee, ...at })
			if (input.shippingFee) fc.placeShippingFee({ ...input.shippingFee, ...at })
			await this.fees.save(fc, tx)
			await this.domainEventRepository.save(
				new FeesConfigurationUpdatedEvent({
					entityId: fc.id.value,
					ownerId: input.storeId,
					payload: { feesConfiguration: fc.toJSON(), effectiveStartDate: input.effectiveFrom, previousFeesConfigurationId: null },
				}),
				tx,
			)
			return { feesConfigurationId: fc.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

