const {
	ShippingFeeSchema: _shippingFee,
	GatewayFeeRateSchema: _gatewayFeeRate,
	CheckoutFeeSchema: _checkoutFee,
	RevenueTaxSchema: _revenueTax,
	MarketingTaxRateSchema: _marketingTaxRate,
	...financeObjectsFiltered
} = financeObjects
const { OrderOverrideFieldsSchema: _orderOverride, ...salesObjectsFiltered } = salesObjects
const {
	ProductCostOptionValueSchema: _pcoValue,
	ProductCostOptionSchema: _pco,
	ProductCostOptionItemSchema: _pcoItem,
	...catalogObjectsFiltered
} = catalogObjects
const {
	PhonePlainSchema: _phonePlain,
	...sharedObjectsFiltered
} = sharedObjects
openapi.registerSchemas({
	...sharedObjectsFiltered,
	...authObjectsFiltered,
	...financeObjectsFiltered,
	...salesObjectsFiltered,
	...catalogObjectsFiltered,
