import * as authObjects from '@auth/objects'
import * as financeObjects from '@finance/objects'
import * as salesObjects from '@sales/objects'
import * as catalogObjects from '@catalog/objects'

const ctx = await BoundedContext.create({
	name: '',
	root: true,
	controllers: {}, // root has no controllers; child contexts supply them
	registry: ALL_REGISTRIES,
	setup: async container => {
		const externalMediator = container.resolve(ExternalMediator as any) as ExternalMediator
		const outboxDispatcher = container.resolve(OutboxDispatcher as any) as OutboxDispatcher
		await externalMediator.start()
		outboxDispatcher.start()
	},
})

// Register enums so controller schemas can resolve enum component names
// by matching sorted value lists (handleEnumSchema → resolveEnumName). Without this,
// enum components get generated names like `ReactionType2` whenever the path-based
// fallback collides with a sibling field. See cc-bp-13.
openapi.registerEnums({ ...wireEnums, ...authEnums, ...billingEnums, ...catalogEnums, ...analyticsEnums })

// Register all value-object schemas so any controller body/response that embeds
// them emits a `$ref: '#/components/schemas/<Name>'` instead of inlining.
//
// Exclusions (per-schema, with rationale):
//
//   Schemas with a top-level .refine() MUST be excluded: addRefinementsRecursively
//   (in zodToJsonSchema) adds x-tpl-zod-refinements to any $ref node that points at
//   the registered schema, producing { $ref: '...', 'x-tpl-zod-refinements': [...] }
//   which fails validateRefinementPlacement (refinements are only allowed on named
//   component roots, not on inline $ref usages).
//
//   EmailSchema         — z.string().transform().refine() → top-level refine
//   PhonePlainSchema    — z.string().refine()            → top-level refine
//                         (confirmed bug: SignUp.ts uses it as a body field)
//   RevenueTaxSchema    — z.historical({...}) → top-level refine
//   GatewayFeeRateSchema— z.historical({...}) → top-level refine
//   CheckoutFeeSchema   — z.historical({...}) → top-level refine
//   MarketingTaxRateSchema — z.historical({...}) → top-level refine
//
//   ShippingFeeSchema   — z.historical(z.discriminatedUnion(...)) wraps the union in
//                         .refine(); the outer def is no longer recognized as a
//                         discriminated union by processDiscriminatedUnions, so
//                         variants won't lift into named variant components cleanly.
//
//   OrderOverrideFieldsSchema  — z.instance(Money/...) fields serialize as {} in
//                                io:'input' (unrepresentable transform), making the
//                                generated schema useless for SDK consumers.
//
//   ProductCostOptionValueSchema — z.historical with z.instance(ProductCostOptionItem)
//                                  → top-level refine + unrepresentable instance fields
//   ProductCostOptionSchema      — z.instance(Id) + nested instance arrays → all {}
//   ProductCostOptionItemSchema  — z.instance(Id/Money) → all {}
//
// Non-schema class/type exports (Timeline, Phone, PhoneBuilder, Money, MultiCurrencyMoney,
// Email, ProductCostOption, ProductCostOptionItem, GatewayFee/Tax types, etc.) are
// silently skipped by registerSchemas (no _zod / ~standard marker).
const { EmailSchema: _email, ...authObjectsFiltered } = authObjects
const {
	ShippingFeeSchema: _shippingFee,
	GatewayFeeRateSchema: _gatewayFeeRate,
	CheckoutFeeSchema: _checkoutFee,
